package org.jsoup.select;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import org.jsoup.helper.StringUtil;
import org.jsoup.helper.Validate;
import org.jsoup.parser.TokenQueue;
import org.jsoup.select.Evaluator;
import org.jsoup.select.QueryParser;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertThrows;

public class QueryParser_parse_TriageGen0Test {

    @Test
    public void testParse_EmptyQuery() {
        // given
        String query = "";
        QueryParser p = new QueryParser(query);

        // when
        Evaluator evaluator = p.parse();

        // then
        assertEquals(new ArrayList<>(), evaluator.selectors());
    }

    @Test
    public void testParse_NullQuery() {
        // given
        String query = null;
        QueryParser p = new QueryParser(query);

        // when, then
        assertThrows(IllegalArgumentException.class, () -> p.parse());
    }

    @Test
    public void testParse_SimpleQuery() {
        // given
        String query = "div";
        QueryParser p = new QueryParser(query);

        // when
        Evaluator evaluator = p.parse();

        // then
        assertEquals(List.of("div"), evaluator.selectors());
    }

    @Test
    public void testParse_MultipleQueries() {
        // given
        String query = "div, p";
        QueryParser p = new QueryParser(query);

        // when
        Evaluator evaluator = p.parse();

        // then
        assertEquals(List.of("div", "p"), evaluator.selectors());
    }

    @Test
    public void testParse_QueryWithSpaces() {
        // given
        String query = "div p";
        QueryParser p = new QueryParser(query);

        // when
        Evaluator evaluator = p.parse();

        // then
        assertEquals(List.of("div", "p"), evaluator.selectors());
    }

    @Test
    public void testParse_QueryWithSpecialChars() {
        // given
        String query = "div#id > p";
        QueryParser p = new QueryParser(query);

        // when
        Evaluator evaluator = p.parse();

        // then
        assertEquals(List.of("div#id", "> p"), evaluator.selectors());
    }

    @Test
    public void testParse_QueryWithCommaAndSpace() {
        // given
        String query = "div, p, span";
        QueryParser p = new QueryParser(query);

        // when
        Evaluator evaluator = p.parse();

        // then
        assertEquals(List.of("div", "p", "span"), evaluator.selectors());
    }
}
